INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5824234, 848476, 53200, '<td valign="top">I laughed out loud when I saw this - it is such a great memento for all of them!!!</td>', 'I laughed out loud when I saw this - it is such a great memento for all of them!!!', '2010-01-22 16:19:07.000000', NULL, 1),
(5824235, 848467, 53200, '<td valign="top">What a great capture - it leaves one with a feeling of the danger involved and relief for their safety.</td>', 'What a great capture - it leaves one with a feeling of the danger involved and relief for their safety.', '2010-01-22 16:19:09.000000', NULL, 1),
(5824236, 848356, 53200, '<td valign="top">I love the tilted head - so different from most owl shots!</td>', 'I love the tilted head - so different from most owl shots!', '2010-01-22 16:19:11.000000', NULL, 1),
(5824237, 848040, 53200, '<td valign="top">This is so beautiful - what a great story it tells!</td>', 'This is so beautiful - what a great story it tells!', '2010-01-22 16:19:15.000000', NULL, 1),
(5824238, 848598, 53200, '<td valign="top">I loved this - the impression I get is more serene to me than stormy - but you were the one there to experience it!</td>', 'I loved this - the impression I get is more serene to me than stormy - but you were the one there to experience it!', '2010-01-22 16:19:17.000000', NULL, 1),
(5824239, 848699, 53200, '<td valign="top">Beautiful eyes - love the soft glow around her.</td>', 'Beautiful eyes - love the soft glow around her.', '2010-01-22 16:19:18.000000', NULL, 1),
(5824240, 848329, 53200, '<td valign="top">This is a very moving photo - the eyes speak of such sadness.</td>', 'This is a very moving photo - the eyes speak of such sadness.', '2010-01-22 16:19:20.000000', NULL, 1),
(5824241, 847036, 53200, '<td valign="top">Great detail - wonderful capture!</td>', 'Great detail - wonderful capture!', '2010-01-22 16:19:21.000000', NULL, 1),
(5824242, 848030, 53200, '<td valign="top">They look petrified - such great eyes!!!</td>', 'They look petrified - such great eyes!!!', '2010-01-22 16:19:22.000000', NULL, 1),
