(5824432, 848804, 327, '<td valign="top">How pretty she is and how pretty your shot is! I love light and shadow.</td>', 'How pretty she is and how pretty your shot is! I love light and shadow.', '2010-01-22 17:26:58.000000', NULL, 1),
(5824433, 848840, 96881, '<td valign="top">The subject blends too much into the surroundings, and the overall image is not sharp enough</td>', 'The subject blends too much into the surroundings, and the overall image is not sharp enough', '2010-01-22 17:27:23.000000', NULL, 1),
(5824435, 848468, 327, '<td valign="top">One little Loon or duck in the mist. Nice capture.</td>', 'One little Loon or duck in the mist. Nice capture.', '2010-01-22 17:27:26.000000', NULL, 1),
(5824436, 848818, 43774, '<td valign="top">Nice perspective, good tones. Looks slightly tilted to the left.</td>', 'Nice perspective, good tones. Looks slightly tilted to the left.', '2010-01-22 17:27:58.000000', NULL, 1),
