INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5826506, 848646, 103048, '<td valign="top">doesn''t really capture attention in my opinion..</td>', 'doesn''t really capture attention in my opinion..', '2010-01-23 10:51:12.000000', NULL, 1),
(5826507, 848834, 43774, '<td valign="top">Very interesting scene, always nice to see other cultures.</td>', 'Very interesting scene, always nice to see other cultures.', '2010-01-23 10:51:24.000000', NULL, 1),
(5826509, 848733, 327, '<td valign="top">He seems sad. I think you caught his emotions so well. Handsome kid.</td>', 'He seems sad. I think you caught his emotions so well. Handsome kid.', '2010-01-23 10:51:57.000000', NULL, 1),
(5826510, 848325, 43774, '<td valign="top">Good action shot, nice reflections. Good backlighting in the wings but would like to see this from a different angle so there was more light on the front of the birds.</td>', 'Good action shot, nice reflections. Good backlighting in the wings but would like to see this from a different angle so there was more light on the front of the birds.', '2010-01-23 10:52:01.000000', NULL, 1),
(5826511, 847842, 327, '<td valign="top">The color and focus are just wonderful. Pretty bird.</td>', 'The color and focus are just wonderful. Pretty bird.', '2010-01-23 10:52:28.000000', NULL, 1),
(5826512, 847992, 43774, '<td valign="top">Very nice perspective and composition but in my opinion the over the top HDR processing has ruined an otherwise excellent photo.</td>', 'Very nice perspective and composition but in my opinion the over the top HDR processing has ruined an otherwise excellent photo.', '2010-01-23 10:52:29.000000', NULL, 1),
(5826513, 847691, 103048, '<td valign="top">Beautiful. However, with this composition, the eye is drawn to the sea / mist, which isn''t as attractive... perhaps if you had stooped lower and made the rocks more prominent</td>', 'Beautiful. However, with this composition, the eye is drawn to the sea / mist, which isn''t as attractive... perhaps if you had stooped lower and made the rocks more prominent', '2010-01-23 10:52:37.000000', NULL, 1),
(5826514, 848801, 43774, '<td valign="top">Another photo where the subject matter is great and the composition very good but the over the top HDR processing ruins it for me.</td>', 'Another photo where the subject matter is great and the composition very good but the over the top HDR processing ruins it for me.', '2010-01-23 10:52:57.000000', NULL, 1),
(5826515, 848918, 327, '<td valign="top">LOL yes I guess she is a black widow..and with mystery too.</td>', 'LOL yes I guess she is a black widow..and with mystery too.', '2010-01-23 10:53:01.000000', NULL, 1),
(5826516, 847026, 103048, '<td valign="top">Beautiful capture. not many people would get the luxury to capture something like this</td>', 'Beautiful capture. not many people would get the luxury to capture something like this', '2010-01-23 10:53:05.000000', NULL, 1),
(5826517, 847469, 43774, '<td valign="top">Ha that''s pretty neat! Good candid street scene.</td>', 'Ha that''s pretty neat! Good candid street scene.', '2010-01-23 10:53:12.000000', NULL, 1),
(5826518, 847046, 86218, '<td valign="top">The composition works perfectly for me but the post processing does not work entirely. Still to much overexposed on the right for my taste</td>', 'The composition works perfectly for me but the post processing does not work entirely. Still to much overexposed on the right for my taste', '2010-01-23 10:53:18.000000', NULL, 1),
(5826519, 848695, 103048, '<td valign="top">hmm doesn''t really do it for me.</td>', 'hmm doesn''t really do it for me.', '2010-01-23 10:53:19.000000', NULL, 1),
(5826520, 847984, 43774, '<td valign="top">Interesting perspective, B&amp;W works well.</td>', 'Interesting perspective, B&W works well.', '2010-01-23 10:53:25.000000', NULL, 1),
(5826521, 848865, 43774, '<td valign="top">Very good action shot, good exposure.</td>', 'Very good action shot, good exposure.', '2010-01-23 10:53:38.000000', NULL, 1),
(5826523, 847476, 43774, '<td valign="top">The waterfalls looks great, I like the look of the flowing water. The rest of the photo is too dark for my tastes.</td>', 'The waterfalls looks great, I like the look of the flowing water. The rest of the photo is too dark for my tastes.', '2010-01-23 10:54:10.000000', NULL, 1),
(5826524, 848699, 327, '<td valign="top">Pretty brown eyes and pretty shot. I like this one VERY much, good good work.</td>', 'Pretty brown eyes and pretty shot. I like this one VERY much, good good work.', '2010-01-23 10:54:22.000000', NULL, 1),
(5826525, 848598, 43774, '<td valign="top">Very nice scene and composition. Has a pinkish tint that I''m not overly fond of.</td>', 'Very nice scene and composition. Has a pinkish tint that I''m not overly fond of.', '2010-01-23 10:54:33.000000', NULL, 1),
(5826526, 848830, 86218, '<td valign="top">Wow. When will I ever get to see something like this. Retired, kids out of house..and money to travel. Very nice</td>', 'Wow. When will I ever get to see something like this. Retired, kids out of house..and money to travel. Very nice', '2010-01-23 10:54:47.000000', NULL, 1),
(5826527, 847376, 43774, '<td valign="top">Nice close-up, pretty girl, exposed well.</td>', 'Nice close-up, pretty girl, exposed well.', '2010-01-23 10:54:56.000000', NULL, 1),
(5826528, 847645, 327, '<td valign="top">Very professionally donw. Everything is wonderful here. What a great shot of a pretty girl. WOW</td>', 'Very professionally donw. Everything is wonderful here. What a great shot of a pretty girl. WOW', '2010-01-23 10:55:48.000000', NULL, 1),
(5826530, 848380, 45243, '<td valign="top">Great expression...</td>', 'Great expression...', '2010-01-23 10:56:02.000000', NULL, 1),
(5826531, 847075, 43774, '<td valign="top">Nice gaze you captured on the cat. Shame about the one in the background. Did you use topaz or HDR on this? Bordering on too much in my opinion. The focus and clarity on the face is wonderful though.</td>', 'Nice gaze you captured on the cat. Shame about the one in the background. Did you use topaz or HDR on this? Bordering on too much in my opinion. The focus and clarity on the face is wonderful though.', '2010-01-23 10:56:04.000000', NULL, 1),
(5826533, 848270, 327, '<td valign="top">Ethereal yes!! How nice you really have a great shot here.</td>', 'Ethereal yes!! How nice you really have a great shot here.', '2010-01-23 10:56:29.000000', NULL, 1),
(5826534, 847745, 43774, '<td valign="top">The person adds a lot to this photo and gives a sense of scale. Would like to see just a bit more contrast.</td>', 'The person adds a lot to this photo and gives a sense of scale. Would like to see just a bit more contrast.', '2010-01-23 10:57:07.000000', NULL, 1),
(5826535, 847105, 43774, '<td valign="top">Very pretty, nice pose and gaze, I like the tones as well.</td>', 'Very pretty, nice pose and gaze, I like the tones as well.', '2010-01-23 10:57:20.000000', NULL, 1),
(5826538, 847393, 43774, '<td valign="top">Nice pose, classic portrait of an eagle. I might have cropped a bit off the right so it wasn''t so centered.</td>', 'Nice pose, classic portrait of an eagle. I might have cropped a bit off the right so it wasn''t so centered.', '2010-01-23 10:57:52.000000', NULL, 1),
(5826539, 848317, 327, '<td valign="top">Title is perfect. Interesting image. I don''t know if it''s a roof or leaf or just what? Either or I like it.</td>', 'Title is perfect. Interesting image. I don''t know if it''s a roof or leaf or just what? Either or I like it.', '2010-01-23 10:57:58.000000', NULL, 1),
(5826542, 847932, 43774, '<td valign="top">Very nice scene, I like the mist in the distance.</td>', 'Very nice scene, I like the mist in the distance.', '2010-01-23 10:58:24.000000', NULL, 1),
(5826544, 848902, 30982, '<td valign="top">Nicely done.  Would make a nice calendar or card print.</td>', 'Nicely done.  Would make a nice calendar or card print.', '2010-01-23 10:59:37.000000', NULL, 1),
(5826545, 847249, 327, '<td valign="top">Beautiful shot.</td>', 'Beautiful shot.', '2010-01-23 10:59:45.000000', NULL, 1),
(5826546, 847391, 45243, '<td valign="top">beautiful cityscape</td>', 'beautiful cityscape', '2010-01-23 11:00:00.000000', NULL, 1),
(5826547, 848515, 30982, '<td valign="top">Sweetly nostalgic!  Lovely arrangement of the items in the frame and the toning suits this very well!</td>', 'Sweetly nostalgic!  Lovely arrangement of the items in the frame and the toning suits this very well!', '2010-01-23 11:00:07.000000', NULL, 1),
(5826549, 848801, 30982, '<td valign="top">Whimsical in a way, and I think that the processing encourages this feel.  Some may consider it (the processing) a bit much but I think it suis this very well!  I like the overall tilt, too.  Quite like this!</td>', 'Whimsical in a way, and I think that the processing encourages this feel.  Some may consider it (the processing) a bit much but I think it suis this very well!  I like the overall tilt, too.  Quite like this!', '2010-01-23 11:01:01.000000', NULL, 1),
(5826550, 847185, 327, '<td valign="top">Fascinating looking place.</td>', 'Fascinating looking place.', '2010-01-23 11:01:50.000000', NULL, 1),
(5826552, 848838, 30982, '<td valign="top">What a colorful and whimsical photo!  I like that the box is just a bit off level, and I really like the flowers below.  Nice job with exposure and focus - a good complete photograph!</td>', 'What a colorful and whimsical photo!  I like that the box is just a bit off level, and I really like the flowers below.  Nice job with exposure and focus - a good complete photograph!', '2010-01-23 11:02:03.000000', NULL, 1),
(5826553, 847382, 327, '<td valign="top">Oh wow all this color, action and eye contact too! Love it.</td>', 'Oh wow all this color, action and eye contact too! Love it.', '2010-01-23 11:02:16.000000', NULL, 1),
(5826557, 848454, 30982, '<td valign="top">Good job!  Love that you caught the action at just the right point and B&amp;W works well to keep the focus on that action.  I especially like the graceful pose of the bird.  Well done!</td>', 'Good job!  Love that you caught the action at just the right point and B&W works well to keep the focus on that action.  I especially like the graceful pose of the bird.  Well done!', '2010-01-23 11:03:20.000000', NULL, 1),
(5826559, 848186, 327, '<td valign="top">How cool. I would love to go there. All the boats are rest. Neat shot.</td>', 'How cool. I would love to go there. All the boats are rest. Neat shot.', '2010-01-23 11:03:57.000000', NULL, 1),
(5826560, 847391, 44877, '<td valign="top">I''m sure you''re hearing this a lot - whatever is in the bottom left corner is disturbing to the whole image. Otherwise it''s a good photo.</td>', 'I''m sure you''re hearing this a lot - whatever is in the bottom left corner is disturbing to the whole image. Otherwise it''s a good photo.', '2010-01-23 11:04:15.000000', NULL, 1),
(5826561, 848467, 30982, '<td valign="top">What an excellent tableau!  Great catch and perfect tming.  There''s a palpable tension, both in the young man''s stand, the horse''s massive bulk nearly airborn, but mostly in the man''s face and hand pulling the other ut of the way.  Top this all off with the red ribbon - obviously an award winning animal - and this is a wonderful bit of both photojournalism and slice of life.</td>', 'What an excellent tableau!  Great catch and perfect tming.  There''s a palpable tension, both in the young man''s stand, the horse''s massive bulk nearly airborn, but mostly in the man''s face and hand pulling the other ut of the way.  Top this all off with the red ribbon - obviously an award winning animal - and this is a wonderful bit of both photojournalism and slice of life.', '2010-01-23 11:04:59.000000', NULL, 1),
(5826563, 847379, 86218, '<td valign="top">Lovely church and going through the trees normally works well but here the trees are not sharp - especially branches in middle coming down. Processed to much and the white sin sky coming into black does not work to well</td>', 'Lovely church and going through the trees normally works well but here the trees are not sharp - especially branches in middle coming down. Processed to much and the white sin sky coming into black does not work to well', '2010-01-23 11:05:07.000000', NULL, 1),
