(5826783, 848549, 45243, '<td valign="top">paradise indeed !!</td>', 'paradise indeed !!', '2010-01-23 12:04:37.000000', NULL, 1),
(5826789, 848895, 44877, '<td valign="top">Nice - very Escher-esque.</td>', 'Nice - very Escher-esque.', '2010-01-23 12:09:19.000000', NULL, 1),
