(5826815, 847472, 113634, '<td valign="top">this picture is adorable!</td>', 'this picture is adorable!', '2010-01-23 12:26:51.000000', NULL, 1),
(5826817, 848883, 76335, '<td valign="top">Is that cash being dropped? I wonder how many of the voters missed that. Great. Would like to see it in black and white.</td>', 'Is that cash being dropped? I wonder how many of the voters missed that. Great. Would like to see it in black and white.', '2010-01-23 12:28:55.000000', NULL, 1),
(5826818, 848788, 92577, '<td valign="top">shades of 1970s rock album covers - (that means I like it!)</td>', 'shades of 1970s rock album covers - (that means I like it!)', '2010-01-23 12:29:03.000000', NULL, 1),
(5826819, 848415, 76335, '<td valign="top">The crazy border really works well. Creative.</td>', 'The crazy border really works well. Creative.', '2010-01-23 12:29:31.000000', NULL, 1),
(5826821, 848808, 76335, '<td valign="top">Great electric colors, effectively framed.</td>', 'Great electric colors, effectively framed.', '2010-01-23 12:30:09.000000', NULL, 1),
(5826822, 847905, 92577, '<td valign="top">I liked it last time when there was a crowd of people at the bottom of the picture and I still like it now. - good luck</td>', 'I liked it last time when there was a crowd of people at the bottom of the picture and I still like it now. - good luck', '2010-01-23 12:31:25.000000', NULL, 1),
(5826823, 848846, 76335, '<td valign="top">Great high key lighting without blowing any highlights. It works.</td>', 'Great high key lighting without blowing any highlights. It works.', '2010-01-23 12:32:37.000000', NULL, 1),
(5826825, 847220, 92577, '<td valign="top">cool</td>', 'cool', '2010-01-23 12:32:50.000000', NULL, 1),
