INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5828466, 848905, 100831, '<td valign="top">This makes me laugh. What great perspective. They rather look alike, too.</td>', 'This makes me laugh. What great perspective. They rather look alike, too.', '2010-01-24 00:27:11.000000', NULL, 1),
