(5828468, 847116, 100831, '<td valign="top">The mighty beast. Love the colors and the directness of the stare.</td>', 'The mighty beast. Love the colors and the directness of the stare.', '2010-01-24 00:29:11.000000', NULL, 1),
(5828469, 847235, 100831, '<td valign="top">Excellent shot. Great story here. Good job with the details. 7</td>', 'Excellent shot. Great story here. Good job with the details. 7', '2010-01-24 00:30:29.000000', NULL, 1),
(5828470, 847034, 100831, '<td valign="top">Wonderful portrait. Nice details and striking softness of such a majestic animal.</td>', 'Wonderful portrait. Nice details and striking softness of such a majestic animal.', '2010-01-24 00:31:15.000000', NULL, 1),
