INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5831495, 848880, 34938, '<td valign="top">nice drama in the sky...</td>', 'nice drama in the sky...', '2010-01-25 09:00:45.000000', NULL, 1),
(5831497, 848824, 34938, '<td valign="top">interesting place...nice colour</td>', 'interesting place...nice colour', '2010-01-25 09:01:07.000000', NULL, 1),
(5831499, 848806, 34938, '<td valign="top">nice overall, but lacks contrast</td>', 'nice overall, but lacks contrast', '2010-01-25 09:01:27.000000', NULL, 1),
