(5840048, 848839, 63398, '<td valign="top">Very cute portrait.....5</td>', 'Very cute portrait.....5', '2010-01-28 07:11:07.000000', NULL, 1),
(5840049, 848699, 101117, '<td valign="top">The softening along the left side looks artificial to me, as if added in post processing, and I''m really not a big fan of the soft white border either, it actually distracts me from the main subject of the shot.</td>', 'The softening along the left side looks artificial to me, as if added in post processing, and I''m really not a big fan of the soft white border either, it actually distracts me from the main subject of the shot.', '2010-01-28 07:11:15.000000', NULL, 1),
